 "content": "from collections import deque


def transform(grid):
    """Reverse the color order of nested nonzero shapes in each component."""
    h, w = len(grid), len(grid[0])
    seen = set()
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        q.append((ny, nx))

            boxes = {}
            for y, x in component:
                color = grid[y][x]
                if color not in boxes:
                    boxes[color] = [y, y, x, x]
                else:
                    box = boxes[color]
                    box[0] = min(box[0], y)
                    box[1] = max(box[1], y)
                    box[2] = min(box[2], x)
                    box[3] = max(box[3], x)
            layers = sorted(boxes, key=lambda color: (
                (boxes[color][1] - boxes[color][0] + 1) *
                (boxes[color][3] - boxes[color][2] + 1), color))
            reverse = {color: layers[-1 - i] for i, color in enumerate(layers)}
            for y, x in component:
                out[y][x] = reverse[grid[y][x]]
    return out


